import{_ as t,a,c as s,ac as r}from"./chunks/framework.BSuaGltH.js";const L=JSON.parse('{"title":"PostgreSQL 练习、复习与参考解答","description":"将SQL、NULL、JOIN、分页、MVCC、事务所有权和恢复组合起来检验理解，参考解答与题目分开。","frontmatter":{"title":"PostgreSQL 练习、复习与参考解答","description":"将SQL、NULL、JOIN、分页、MVCC、事务所有权和恢复组合起来检验理解，参考解答与题目分开。","showdocs":{"topics":[{"id":"postgres","title":"PostgreSQL","link":"/topics/postgres/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"PostgreSQL 18 关系数据与事务实践","summary":"将SQL、NULL、JOIN、分页、MVCC、事务所有权和恢复组合起来检验理解，参考解答与题目分开。","status":"active","related":[{"title":"PostgreSQL 操作与命令","link":"/middleware/databases/postgres/plus/ecosystem/postgres-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"PostgreSQL 完整项目：参数化库存预留 CLI","link":"/middleware/databases/postgres/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"PostgreSQL 完整项目：参数化库存预留 CLI · 安装、初始化与运行至完整源码与参数绑定","link":"/middleware/databases/postgres/plus/practice/application-part-01","kind":"应用实践","scope":"general","audience":"general"},{"title":"PostgreSQL 完整项目：参数化库存预留 CLI · 完整测试、反例与执行计划至综合练习","link":"/middleware/databases/postgres/plus/practice/application-part-02","kind":"应用实践","scope":"general","audience":"general"},{"title":"PostgreSQL 建模、NULL、查询与执行计划","link":"/middleware/databases/postgres/base/intermediate/model","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"PostgreSQL：备份、恢复与连接排障","link":"/middleware/databases/postgres/operations"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"PostgreSQL：备份、恢复与连接排障","link":"/middleware/databases/postgres/operations"},"next":false},"headers":[],"relativePath":"middleware/databases/postgres/pro/review/review.md","filePath":"middleware/databases/postgres/pro/review/review.md"}'),o={name:"middleware/databases/postgres/pro/review/review.md"};function i(n,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="postgresql-练习、复习与参考解答" tabindex="-1">PostgreSQL 练习、复习与参考解答 <a class="header-anchor" href="#postgresql-练习、复习与参考解答" aria-label="Permalink to &quot;PostgreSQL 练习、复习与参考解答&quot;">​</a></h1><blockquote><p>本轮仅做正文和源码静态审阅，以下命令、SQL、集成测试及恢复流程均未执行。过去真实运行记录保留在 <code>migration/knowledge-rebuild/m4-next/postgres/verification.md</code> 及其原始日志；历史结果不证明修改后的示例运行通过。</p></blockquote><h2 id="questions" tabindex="-1">先尝试的题目 <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;先尝试的题目 {#questions}&quot;">​</a></h2><p>前置：<a href="/middleware/databases/postgres/plus/practice/application#verification">应用与验证</a>。本页是复习入口，遇到概念不清时按题目回到唯一正文，不再复制完整项目。</p><ol><li>在BEGIN里把book加2后ROLLBACK，事务内和事务后各看到什么？自动提交的UPDATE还能由下一次ROLLBACK撤销吗？</li><li>为什么 <code>CHECK(stock&gt;=0)</code> 仍需要NOT NULL？<code>note=NULL</code> 为何匹配不到缺失备注？</li><li>LEFT JOIN后用COUNT(*)统计预留数，pen为什么得到1？如何只数真正的预留？</li><li>按created_at分页时，许多记录创建时间一样，如何避免同时间的行被漏掉？多页请求是否天然是同一快照？</li><li>A在Repeatable Read读取库存后，B提交更新，A再次普通SELECT和重新开事务SELECT分别怎样？默认Read Committed怎样？</li><li>重复request_id为什么必须比较sku与quantity？在函数成功后直接commit，或失败后直接rollback，有什么问题？</li><li>EXPLAIN ANALYZE一个UPDATE会不会写数据？Index Only Scan是否保证完全不读堆？</li><li>pg_restore --list成功后是否可以删除源库？恢复目标存在时为什么脚本要失败？</li></ol><h2 id="practice" tabindex="-1">综合实践：请求结果查询 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;综合实践：请求结果查询 {#practice}&quot;">​</a></h2><p>给库存CLI添加 <code>get request_id</code> 命令，只读查询reservations。先写两个 CLI 测试规格：一个键不存在时退出1；一个键包含中文、单引号及SQL片段时按原值返回。合法键应先用 reserve 建立，再调用 get；只测数据库查询函数不能证明 CLI 退出码。再证明重复get不改变products.stock。遵循现有参数绑定和固定表名，不需要额外抽象或网络服务。</p><p>进阶思考：reserve成功但客户端在打印前断开，应如何判断最终结果？如果客户端每次重试都生成不同键，为什么事务原子性不能防重复扣减？先画出提交前失败、提交后响应前失败的时间线，再看下面答案。</p><h2 id="answers" tabindex="-1">参考解答 <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;参考解答 {#answers}&quot;">​</a></h2><p><strong>回滚与自动提交。</strong> 事务内book从3变5，ROLLBACK后回3。自动提交的UPDATE已构成独立事务并提交，后开的事务不能撤销过去提交；只能执行新的补偿业务动作，并考虑其间其他写入。</p><p><strong>NULL与约束。</strong> CHECK只拒绝false，NULL比较产生unknown可通过，因此NOT NULL独立表达必须有值。缺失备注应使用 <code>IS NULL</code>；<code>COUNT(note)</code>忽略NULL，而COUNT(*)数行。这两条规则需要一起理解，不能把NULL当普通字符串。</p><p><strong>JOIN与分页。</strong> LEFT JOIN为未匹配的pen保留一行，COUNT(*)数到这行；改 <code>COUNT(r.request_id)</code> 只数右表非空主键。按时间分页用 <code>WHERE (created_at,request_id) &gt; (%s,%s) ORDER BY created_at,request_id LIMIT 10</code>，完整游标必须包含唯一决胜键。不同HTTP/CLI调用通常是不同快照，分页不保证全程冻结数据。</p><p><strong>隔离与重试。</strong> Repeatable Read首个查询建立快照，A第二次普通SELECT读旧值，新事务读已提交新值；Read Committed下一条语句读新快照。Serializable或Repeatable Read下并发写可能报40001，应用应有限重试整个业务事务。本课隔离测试覆盖快照与锁超时；未把未运行的生产负载序列化重试算验收。</p><p><strong>幂等与事务所有权。</strong> 在 Psycopg 的 <code>conn.transaction()</code> 块内调用 commit/rollback 会被拒绝并抛出 ProgrammingError，不能描述成“提交成功使外层回滚失效”；给当前实现插入 commit 后，测试可能先因异常类型与预期不符而失败。越权提交问题发生在绕开这些上下文保护、手工管理事务的代码中。<a href="https://www.psycopg.org/psycopg3/docs/api/connections.html#psycopg.Connection.transaction" target="_blank" rel="noopener noreferrer">Psycopg 连接 API</a>说明此限制。 同键换参数代表业务冲突，静默返回成功会掩盖错误请求。库函数不能替调用者提交或回滚外层事务；<code>conn.transaction()</code> 使用SAVEPOINT保护本次操作。外层异常仍撤销内部成功操作，内部失败可被外层捕获且保留先前修改。成功提交后响应丢失，应复用同一request_id重试；每次换键会被当作新请求。</p><p><strong>查询实现。</strong> 在只读分支执行 <code>conn.execute(&quot;SELECT request_id,sku,quantity FROM reservations WHERE request_id=%s&quot;, (request_id,)).fetchone()</code>，None时返回明确错误，非None序列化结果；不要插值SQL。测试先记stock，执行get两次，断言两次结果一致且stock不变。不需要为这项练习复制新schema，正式完整CLI仍以已交付三个命令为准。</p><p><strong>计划与恢复。</strong> EXPLAIN ANALYZE实际执行UPDATE，包含锁和写入成本；Index Only Scan还需根据visibility map决定是否访问堆，历史记录中 Heap Fetches 为10。pg_restore --list只读归档目录，恢复应在空目标导入，比较结构约束、排序数据及业务查询；还应运行代表性应用读写、检查角色权限和扩展依赖。脚本拒绝已有目标是为了避免覆盖未知数据，不代表备份文件有错。</p><h2 id="scope" tabindex="-1">自检与后续边界 <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;自检与后续边界 {#scope}&quot;">​</a></h2><p>能够独立解释“语句快照/事务快照”“数据库约束/应用验证”“唯一键/业务幂等”“函数事务/调用者事务”“可读归档/可恢复业务”五组区别，即可完成本路线的理论自检。本轮只静态审阅，7项集成测试与独立库恢复是未执行的读者实践规格，历史运行结果见页首所述记录，不能据此认定当前版本实践闭环已重新运行通过。单机容器不能证明生产高可用；复制、故障切换、连续WAL与PITR、分区、大规模索引、权限治理和容量基准仍需要专项课程，不通过删去边界来冒称全部PostgreSQL能力已验证。</p>',18)])])}const u=t(o,[["render",i]]);export{L as __pageData,u as default};
